820:     /// the `SkipList`, not the `Guard`.
821:     fn search_bound<'a, Q>(
822:         &'a self,
823:         bound: Bound<&Q>,
824:         upper_bound: bool,
825:         guard: &'a Guard,
826:     ) -> Option<NodeRef<'a, K, V>>
