832:             'search: loop {
833:                 // The current level we're at.
834:                 let mut level = self.hot_data.max_height.load(Ordering::Relaxed);
835: 
836:                 // Fast loop to skip empty tower levels.
837:                 while level >= 1
838:                     && self
839:                         .head
840:                         .get_level(level - 1)
841:                         .load(Ordering::Relaxed, guard)
842:                         .is_null()
843:                 {
844:                     level -= 1;
845:                 }
846: 
847:                 // The current best node
848:                 let mut result = None;
849: 
850:                 // The predecessor node
851:                 let mut pred = self.head.as_tower();
852: 
853:                 while level >= 1 {
854:                     level -= 1;
855: 
856:                     // Two adjacent nodes at the current level.
857:                     let mut curr = pred.get_level(level).load_consume(guard);
858: 
859:                     // If `curr` is marked, that means `pred` is removed and we have to restart the
860:                     // search.
861:                     if curr.tag() == 1 {
862:                         continue 'search;
863:                     }
864: 
865:                     // Iterate through the current level until we reach a node with a key greater
866:                     // than or equal to `key`.
867:                     while let Some(c) = NodeRef::from_shared(curr) {
868:                         let succ = c.get_level(level).load_consume(guard);
869: 
870:                         if succ.tag() == 1 {
871:                             if let Some(c) = self.help_unlink(pred.get_level(level), c, succ, guard)
872:                             {
873:                                 // On success, continue searching through the current level.
874:                                 curr = c;
875:                                 continue;
876:                             } else {
877:                                 // On failure, we cannot do anything reasonable to continue
878:                                 // searching from the current position. Restart the search.
879:                                 continue 'search;
880:                             }
881:                         }
882: 
883:                         // If `curr` contains a key that is greater than (or equal) to `key`, we're
884:                         // done with this level.
885:                         //
886:                         // The condition determines whether we should stop the search. For the upper
887:                         // bound, we return the last node before the condition became true. For the
888:                         // lower bound, we return the first node after the condition became true.
889:                         if upper_bound {
890:                             if !below_upper_bound(&bound, &c.key) {
891:                                 break;
892:                             }
893:                             result = Some(c);
894:                         } else if above_lower_bound(&bound, &c.key) {
895:                             result = Some(c);
896:                             break;
897:                         }
898: 
899:                         // Move one step forward.
900:                         pred = c.as_tower();
901:                         curr = succ;
902:                     }
903:                 }
904: 
905:                 return result;
906:             }
907:         }
908:     }
