918:                 // The result of this search.
919:                 let mut result = Position {
920:                     found: None,
921:                     left: [self.head.as_tower(); MAX_HEIGHT],
922:                     right: [Shared::null(); MAX_HEIGHT],
923:                 };
924: 
925:                 // The current level we're at.
926:                 let mut level = self.hot_data.max_height.load(Ordering::Relaxed);
927: 
928:                 // Fast loop to skip empty tower levels.
929:                 while level >= 1
930:                     && self
931:                         .head
932:                         .get_level(level - 1)
933:                         .load(Ordering::Relaxed, guard)
934:                         .is_null()
935:                 {
936:                     level -= 1;
937:                 }
938: 
939:                 // The predecessor node
940:                 let mut pred = self.head.as_tower();
941: 
942:                 while level >= 1 {
943:                     level -= 1;
944: 
945:                     // Two adjacent nodes at the current level.
946:                     let mut curr = pred.get_level(level).load_consume(guard);
947: 
948:                     // If `curr` is marked, that means `pred` is removed and we have to restart the
949:                     // search.
950:                     if curr.tag() == 1 {
951:                         continue 'search;
952:                     }
953: 
954:                     // Iterate through the current level until we reach a node with a key greater
955:                     // than or equal to `key`.
956:                     while let Some(c) = NodeRef::from_shared(curr) {
957:                         let succ = c.get_level(level).load_consume(guard);
958: 
959:                         if succ.tag() == 1 {
960:                             if let Some(c) = self.help_unlink(pred.get_level(level), c, succ, guard)
961:                             {
962:                                 // On success, continue searching through the current level.
963:                                 curr = c;
964:                                 continue;
965:                             } else {
966:                                 // On failure, we cannot do anything reasonable to continue
967:                                 // searching from the current position. Restart the search.
968:                                 continue 'search;
969:                             }
970:                         }
971: 
972:                         // If `curr` contains a key that is greater than or equal to `key`, we're
973:                         // done with this level.
974:                         match c.key.compare(key) {
975:                             cmp::Ordering::Greater => break,
976:                             cmp::Ordering::Equal => {
977:                                 result.found = Some(c);
978:                                 break;
979:                             }
980:                             cmp::Ordering::Less => {}
981:                         }
982: 
983:                         // Move one step forward.
984:                         pred = c.as_tower();
985:                         curr = succ;
986:                     }
987: 
988:                     // Store the position at the current level into the result.
989:                     result.left[level] = pred;
990:                     result.right[level] = curr;
991:                 }
992: 
993:                 return result;
994:             }
995:         }
996:     }
